mapper.select:
SELECT COUNT(*) FROM follow_up_task
WHERE customer_id = #{customerId}
  AND IFNULL(pet_id, 0) = IFNULL(#{petId}, 0)
  AND type = #{type} AND due_on = #{dueOn}

SELECT id AS customerId, name AS customerName
FROM customer
WHERE is_active = 1 AND birthday IS NOT NULL AND substr(birthday, 6, 5) = #{mmdd}

SELECT l.*, c.name AS customer_name, p.name AS pet_name
FROM contact_log l
JOIN customer c ON c.id = l.customer_id
LEFT JOIN pet p ON p.id = l.pet_id
WHERE l.customer_id = #{customerId}
ORDER BY l.id DESC LIMIT #{limit}
